styles.add(ParagraphStyle(name='H1x',parent=styles['Heading1'],fontSize=17,leading=21,textColor=HexColor('#14213d'),spaceAfter=8))
styles.add(ParagraphStyle(name='H2x',parent=styles['Heading2'],fontSize=11.2,leading=14,textColor=HexColor('#1d4ed8'),spaceBefore=5,spaceAfter=3))
styles.add(ParagraphStyle(name='Bodyx',parent=styles['BodyText'],fontSize=9.2,leading=13.2,textColor=HexColor('#263238'),spaceAfter=5))
styles.add(ParagraphStyle(name='Smallx',parent=styles['BodyText'],fontSize=8.2,leading=11.5,textColor=HexColor('#4b5563'),spaceAfter=4))
styles.add(ParagraphStyle(name='Calloutx',parent=styles['BodyText'],fontSize=9,leading=13,textColor=HexColor('#123047'),backColor=HexColor('#eef5ff'),borderColor=HexColor('#bfdbfe'),borderWidth=.5,borderPadding=7,spaceBefore=5,spaceAfter=7))

def esc(s): return html.escape(str(s)).replace('\n','<br/>')
def footer(canvas,doc):
    canvas.saveState(); w,h=A4
    canvas.setStrokeColor(HexColor('#dbe3ee')); canvas.line(18*mm,15*mm,w-18*mm,15*mm)
    canvas.setFont('Helvetica',8); canvas.setFillColor(HexColor('#64748b'))
    canvas.drawString(18*mm,10*mm,'CSE Study Hub • Concise unit notes')
    canvas.drawRightString(w-18*mm,10*mm,f'Page {doc.page} of 5')
    canvas.restoreState()

def split_chunks(items, n=2):
    # Distribute topic coverage over three middle pages.
    chunks=[[],[],[]]
    for i,item in enumerate(items): chunks[min(2, i*3//max(1,len(items)))].append(item)
    return chunks

def build_pdf(course_id, course_name, idx, unit_title, topics):
    slug=f'{course_id}-unit-{idx+1}'
    path=OUT/(slug+'.pdf')
    doc=SimpleDocTemplate(str(path),pagesize=A4,rightMargin=18*mm,leftMargin=18*mm,topMargin=17*mm,bottomMargin=21*mm,title=f'{course_name} — Unit {idx+1}: {unit_title}',author='CSE Study Hub')
    story=[]
    # PAGE 1 — unit map and learning strategy
    story += [Spacer(1,18*mm),Paragraph('CSE STUDY HUB',styles['CoverSub']),Paragraph(esc(course_name),styles['CoverTitle']),Paragraph(f'UNIT {idx+1} · {esc(unit_title)}',styles['CoverSub']),Spacer(1,5*mm),HRFlowable(width='70%',thickness=1.2,color=HexColor('#3b82f6'),hAlign='CENTER'),Spacer(1,8*mm)]
    story += [Paragraph('What this unit is about',styles['H1x']),Paragraph(f'This unit builds understanding of <b>{esc(unit_title)}</b>. These notes are designed for quick learning and exam revision: learn the meaning, understand the working, practise an example, and finish with comparisons and key terms.',styles['Bodyx'])]
    story += [Paragraph('Syllabus coverage checklist',styles['H2x'])]
    for i,t in enumerate(topics,1): story.append(Paragraph(f'<b>{i}.</b> {esc(t)}',styles['Bodyx']))
    story += [Spacer(1,3*mm),Paragraph('<b>How to study:</b> Read each topic once for meaning, underline definitions and formulas, reproduce diagrams/steps without looking, then answer the revision questions on Page 5.',styles['Calloutx']),Paragraph('Exam answer pattern',styles['H2x']),Paragraph('For a 5-mark answer: (1) definition, (2) labelled diagram or formula, (3) working/components in steps, (4) example/application, and (5) one advantage, limitation or comparison.',styles['Bodyx']),PageBreak()]
    # PAGE 2-4 — full coverage of each topic, 2-3 topics per page
    chunks=split_chunks(topics)
    for pno,chunk in enumerate(chunks, start=2):
        story.append(Paragraph(f'UNIT {idx+1} NOTES · PART {pno-1}',styles['H1x']))
        if not chunk:
            story.append(Paragraph('Connecting the concepts',styles['H2x']))
            story.append(Paragraph(f'Relate the unit topics to the wider subject. Identify the input, process, output and evaluation criteria for {unit_title}. Use a diagram or a small scenario to show how the ideas work together.',styles['Bodyx']))
        for j,t in enumerate(chunk):
            desc=explain(t,course_name,unit_title)
            story.append(KeepTogether([Paragraph(esc(t),styles['H2x']),Paragraph(esc(desc),styles['Bodyx']),Paragraph('<b>Write in your own words:</b> Define the concept, list its important parts/steps, and attach one example from a system, program, workplace or numerical problem.',styles['Smallx'])]))
        # Add practical bridge content so middle pages are useful even for shorter units.
        story += [Spacer(1,2*mm),Paragraph('Connect and apply',styles['H2x']),Paragraph(f'For a practical question on {esc(unit_title)}, first identify which syllabus concept is being tested. State assumptions, draw the relevant structure/flow, work through the steps in order, and finish by interpreting the result. Mention complexity, reliability, accuracy, cost or ethical impact whenever it is relevant.',styles['Bodyx'])]
        story.append(PageBreak())
    # PAGE 5 — quick revision, worked application and exam prompts
    story += [Paragraph('QUICK REVISION & EXAM PRACTICE',styles['H1x']),Paragraph('Key takeaways',styles['H2x'])]
    for t in topics:
        story.append(Paragraph(f'• <b>{esc(t)}</b> — know the definition, core working and one example.',styles['Smallx']))
    story += [Paragraph('Worked-answer framework',styles['H2x']),Paragraph(f'<b>Scenario:</b> A question asks you to explain or apply a concept from {esc(unit_title)}. <b>Step 1:</b> identify the relevant term and define it. <b>Step 2:</b> write the formula, components or ordered process. <b>Step 3:</b> apply it to the given data/scenario. <b>Step 4:</b> state the result and justify it. <b>Step 5:</b> mention one limitation or precaution.',styles['Bodyx'])]
    story += [Paragraph('Self-test questions',styles['H2x'])]
    qs=[f'Define {topics[0]} and explain its importance.',f'Explain the working/steps involved in {topics[min(1,len(topics)-1)]}.',f'Differentiate between two related concepts from {unit_title}.',f'Give one practical application of {topics[-1]} and discuss one limitation.',f'Write a structured 5-mark answer covering the main ideas of {unit_title}.']
    for i,q in enumerate(qs,1): story.append(Paragraph(f'<b>Q{i}.</b> {esc(q)}',styles['Bodyx']))
    story += [Spacer(1,2*mm),Paragraph('<b>Final checklist:</b> I can define every topic · explain the process without notes · reproduce formulas/diagrams · solve one example · compare related concepts.',styles['Calloutx'])]
    doc.build(story,onFirstPage=footer,onLaterPages=footer)
    return path

count=0
for cid,(name,units) in COURSES.items():
    for i,(title,topics) in enumerate(units):
        build_pdf(cid,name,i,title,topics); count+=1
print(f'Created {count} unit PDFs in {OUT}')
